fn main(){ let a: Vec<String> = std::env::args().collect(); let s = std::fs::read_to_string(&a[1]).unwrap(); let mut o = resvg::usvg::Options::default(); o.fontdb_mut().load_fonts_dir(&a[2]); let t = resvg::usvg::Tree::from_str(&s,&o).unwrap(); let mut p = resvg::tiny_skia::Pixmap::new(10,10).unwrap(); resvg::render(&t, Default::default(), &mut p.as_mut()); println!("{}", serde_json::json!({"n": p.data().len()})); }
